class LazySingleton {
  const LazySingleton({this.as});

  final Type? as;
}

const lazySingleton = LazySingleton();

class ChatClient {
  void connect() {}
}

class Singleton {
  const Singleton();
}

const singleton = Singleton();

class Injectable {
  const Injectable();
}

const injectable = Injectable();

import 'di/chat_client.dart';

class ChatScreen {
  ChatScreen(this.client);

  final ChatClient client;
}

import 'di/chat_client.dart';

class ChatView {
  ChatView(this.client);

  final ChatClient client;
}

import 'di/chat_client.dart';

@lazySingleton
class ChatLogger {
  final ChatClient client;

  ChatLogger(this.client);
}

import 'di/chat_client.dart';

class Named {
  const Named(this.name);

  final String name;
}

class ChatSender {
  ChatSender({
    @Named('chat') required String channel,
    required ChatClient client,
  });
}

import 'di/chat_client.dart';

class ChatList {
  ChatList(this.client);

  final ChatClient client;
}

import 'di/chat_client.dart';

abstract class ChatModule {
  @lazySingleton
  ChatClient chatClient() => ChatClient();
}

class ChatStore {}

class ChatCache {
  ChatCache(this.store);

  final ChatStore store;
}

abstract class ChatHandler {}

class ChatQueue {}

class ChatTimer {}

import 'di/chat_types.dart';

class StoreView {
  StoreView(this.store);

  final ChatStore store;
}

import 'di/chat_client.dart';
import 'di/chat_types.dart';

abstract class StoreModule {
  @lazySingleton
  ChatCache chatCache(ChatStore store) => ChatCache(store);

  @singleton
  ChatQueue chatQueue() => ChatQueue();

  @injectable
  ChatTimer chatTimer() => ChatTimer();
}

import 'di/chat_types.dart';

class HandlerView {
  HandlerView(this.handler);

  final ChatHandler handler;
}

import 'di/chat_client.dart';
import 'di/chat_types.dart';

@LazySingleton(as: ChatHandler)
class TextChatHandler implements ChatHandler {}

import 'di/chat_types.dart';

class QueueView {
  QueueView(this.queue, this.timer);

  final ChatQueue queue;
  final ChatTimer timer;
}
